"use client";

/**
 * Combobox. A Select you can type into: for a list long enough to search
 * (people, countries, labels). The text goes in Field's well; the list drops
 * from it in Select's plastic, with the same flowing highlight. `multiple`
 * keeps each choice as a tag in the well, budding in as it's chosen, with
 * Backspace or its × to take it out; `creatable` offers to add what you typed
 * when nothing matches.
 *
 * Base UI Combobox owns the filtering, the listbox, the active option, the
 * chips' keyboard and every announcement; Echo owns the look. Closed:
 * `options` in, values (strings) out.
 */
import { forwardRef, useId, useMemo, useState, type ReactNode } from "react";
import { Combobox as BaseCombobox } from "@base-ui/react/combobox";
import type { EchoPortalContainer, EchoTextInterop } from "echo-ui-core/types";
import { useLiquidHighlight } from "echo-ui-core/tactile";
import { useSoundOptional } from "echo-ui-core/sound";
import { useControlSize, type ControlSize } from "../size";
import "../select/select.css";
import "../tag/tag.css";
import "./combobox.css";

export interface ComboboxOption {
  value: string;
  label: string;
}

interface ComboboxOwnProps extends EchoTextInterop {
  /** The visible label and the input's accessible name. */
  label: string;
  options: ComboboxOption[];
  /** Several at once, each kept as a tag in the well. */
  multiple?: boolean;
  /** Chosen value (single) or values (multiple), controlled. */
  value?: string | string[] | null;
  defaultValue?: string | string[] | null;
  /** Called with the value (single, or null when cleared) or the values (multiple). */
  onValueChange?: (value: string | string[] | null) => void;
  /**
   * Offer to add what was typed when nothing matches: it becomes an option
   * (value and label the text), chosen at once, and `onCreate` hears about it.
   */
  creatable?: boolean;
  onCreate?: (label: string) => void;
  /** What the list says when nothing matches. Default "No matches". */
  emptyText?: ReactNode;
  /** Height on the control scale. Defaults to the nearest SizeProvider's size. */
  size?: ControlSize;
  container?: EchoPortalContainer;
}

export type ComboboxProps = ComboboxOwnProps;

type Item = ComboboxOption & { create?: string };

const Check = () => (
  <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <path d="M3.5 8.5l3 3 6-7" />
  </svg>
);
const Chevron = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <path d="M6 9l6 6 6-6" />
  </svg>
);
const Cross = () => (
  <svg viewBox="0 0 12 12" aria-hidden>
    <path d="M3 3l6 6M9 3l-6 6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
  </svg>
);

/** `forwardRef` — see the note on `Field`. The ref lands on the input. */
export const Combobox = forwardRef<HTMLInputElement, ComboboxProps>(function Combobox(
  {
    label,
    options,
    multiple = false,
    value,
    defaultValue,
    onValueChange,
    creatable = false,
    onCreate,
    placeholder,
    emptyText = "No matches",
    size: ownSize,
    container,
    id,
    name,
    disabled,
    required,
    readOnly,
    autoFocus,
    onBlur,
    onFocus,
    ...aria
  },
  ref,
) {
  const size = useControlSize(ownSize);
  const autoId = useId();
  const inputId = id ?? autoId;
  const sound = useSoundOptional();
  const glow = useLiquidHighlight();
  const [created, setCreated] = useState<ComboboxOption[]>([]);
  const [query, setQuery] = useState("");
  const all = useMemo(() => [...options, ...created.filter((c) => !options.some((o) => o.value === c.value))], [options, created]);
  const byValue = (v: string) => all.find((o) => o.value === v) ?? { value: v, label: v };

  const q = query.trim();
  const exact = all.some((o) => o.label.toLocaleLowerCase() === q.toLocaleLowerCase());
  const items: Item[] = creatable && q && !exact ? [...all, { value: `create:${q}`, label: `Create “${q}”`, create: q }] : all;

  const toItems = (v: string | string[] | null | undefined) =>
    v === undefined ? undefined : v === null ? null : Array.isArray(v) ? v.map(byValue) : byValue(v);

  const emit = (next: Item | Item[] | null) => {
    const list = Array.isArray(next) ? next : next ? [next] : [];
    const fresh = list.find((i) => i.create);
    if (fresh) {
      const option = { value: fresh.create!, label: fresh.create! };
      setCreated((c) => [...c, option]);
      onCreate?.(option.label);
      list.splice(list.indexOf(fresh), 1, option);
    }
    sound?.play("select");
    setQuery("");
    onValueChange?.(multiple ? list.map((i) => i.value) : (list[0]?.value ?? null));
  };

  const controlledValue = toItems(value);
  const input = (
    <BaseCombobox.Input
      ref={ref}
      className="echo-combobox__input"
      placeholder={placeholder}
      id={inputId}
      {...(autoFocus ? { autoFocus } : {})}
      {...(onBlur ? { onBlur } : {})}
      {...(onFocus ? { onFocus } : {})}
      {...aria}
    />
  );

  return (
    <BaseCombobox.Root
      items={items}
      multiple={multiple as never}
      itemToStringLabel={(i: Item) => i.label}
      itemToStringValue={(i: Item) => i.value}
      isItemEqualToValue={(a: Item, b: Item) => a.value === b.value}
      {...(controlledValue !== undefined ? { value: controlledValue as never } : {})}
      {...(defaultValue !== undefined ? { defaultValue: toItems(defaultValue) as never } : {})}
      onValueChange={(next) => emit(next as Item | Item[] | null)}
      inputValue={query}
      onInputValueChange={setQuery}
      {...(name ? { name } : {})}
      {...(disabled !== undefined ? { disabled } : {})}
      {...(required !== undefined ? { required } : {})}
      {...(readOnly !== undefined ? { readOnly } : {})}
    >
      <div className="echo-combobox" data-size={size} data-multiple={multiple ? "" : undefined}>
        <label className="echo-combobox__label" htmlFor={inputId}>
          {label}
        </label>
        <BaseCombobox.InputGroup className="echo-combobox__well">
          {multiple ? (
            <BaseCombobox.Value>
              {(chosen: Item[]) => (
                <BaseCombobox.Chips className="echo-combobox__chips" aria-label={chosen.length ? `${label}, chosen` : undefined}>
                  {chosen.map((c) => (
                    <BaseCombobox.Chip
                      key={c.value}
                      className="echo-tag echo-combobox__chip"
                      aria-label={c.label}
                      aria-description="Press Backspace or Delete to remove"
                    >
                      <span className="echo-tag__label">{c.label}</span>
                      <BaseCombobox.ChipRemove className="echo-tag__remove" aria-label={`Remove ${c.label}`}>
                        <Cross />
                      </BaseCombobox.ChipRemove>
                    </BaseCombobox.Chip>
                  ))}
                  {input}
                </BaseCombobox.Chips>
              )}
            </BaseCombobox.Value>
          ) : (
            input
          )}
          <BaseCombobox.Trigger className="echo-combobox__trigger" aria-label={`Show ${label} options`}>
            <Chevron />
          </BaseCombobox.Trigger>
        </BaseCombobox.InputGroup>
      </div>
      <BaseCombobox.Portal container={container}>
        <BaseCombobox.Positioner className="echo-select__positioner" side="bottom" align="start" sideOffset={8}>
          <BaseCombobox.Popup ref={glow.container} className="echo-select__popup echo-combobox__popup">
            <span ref={glow.light} className="echo-select__glow" aria-hidden>
              <span ref={glow.shape} className="echo-select__glow-shape" />
            </span>
            <BaseCombobox.Empty className="echo-combobox__empty">{emptyText}</BaseCombobox.Empty>
            <BaseCombobox.List className="echo-combobox__list">
              {(item: Item) => (
                <BaseCombobox.Item
                  key={item.value}
                  value={item}
                  className="echo-select__item"
                  data-create={item.create ? "" : undefined}
                >
                  <span>{item.label}</span>
                  <BaseCombobox.ItemIndicator className="echo-select__indicator">
                    <Check />
                  </BaseCombobox.ItemIndicator>
                </BaseCombobox.Item>
              )}
            </BaseCombobox.List>
          </BaseCombobox.Popup>
        </BaseCombobox.Positioner>
      </BaseCombobox.Portal>
    </BaseCombobox.Root>
  );
});

/**
 * Combobox. Field's label and well, with the text, the chosen tags and a
 * small chevron cap inside it; the list is Select's popup (select.css), the
 * tags are Tag's (tag.css). On the control scale.
 */
.echo-combobox {
  --ctl-h: var(--echo-control-default);
  --ctl-font: var(--echo-text-md);
  --ctl-px: var(--echo-space-8);
  --ctl-radius: var(--echo-radius-xl);
  display: flex;
  flex-direction: column;
  gap: var(--echo-space-4);
  min-width: 0;
}
.echo-combobox[data-size="sm"] {
  --ctl-h: var(--echo-control-compact);
  --ctl-font: var(--echo-text-sm);
  --ctl-px: var(--echo-space-6);
  --ctl-radius: var(--echo-radius-lg);
}
.echo-combobox[data-size="lg"] {
  --ctl-h: var(--echo-control-large);
  --ctl-font: var(--echo-text-lg);
  --ctl-px: var(--echo-space-9);
  --ctl-radius: var(--echo-radius-2xl);
}
.echo-combobox__label {
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-widest, 0.25em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}
.echo-combobox:focus-within .echo-combobox__label {
  color: var(--echo-text);
}
.echo-combobox__well {
  display: flex;
  align-items: center;
  gap: var(--echo-space-3);
  box-sizing: border-box;
  min-height: var(--ctl-h);
  padding-block: 0;
  padding-inline: var(--ctl-px) var(--echo-space-3);
  border-radius: var(--ctl-radius);
  cursor: text;
  background: linear-gradient(
    160deg,
    color-mix(in oklab, var(--echo-well) 72%, var(--echo-shade-ink, black)),
    color-mix(in oklab, var(--echo-lcd) 88%, var(--echo-shade-ink, black))
  );
  box-shadow: var(
    --echo-shadow-well,
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1)))
  );
  transition: box-shadow var(--echo-duration-swap) ease;
}
.echo-combobox__well:focus-within {
  box-shadow:
    inset 0 0 0 var(--echo-border-thick, 2px) var(--echo-accent-ink, var(--echo-accent-glow)),
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.7 * var(--echo-shade, 1) * 100%), transparent);
}
.echo-combobox[data-multiple] .echo-combobox__well {
  padding-block: var(--echo-space-2);
}
.echo-combobox__chips {
  display: flex;
  flex: 1;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--echo-space-2);
  min-width: 0;
}
.echo-combobox__input {
  flex: 1;
  box-sizing: border-box;
  min-width: 6ch;
  height: calc(var(--ctl-h) - 2 * var(--echo-space-2));
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--echo-text);
  caret-color: var(--echo-accent-glow);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--ctl-font);
}
.echo-combobox:not([data-multiple]) .echo-combobox__input {
  height: var(--ctl-h);
}
.echo-combobox__input::placeholder {
  color: var(--echo-text-dim);
}
/* A chosen value buds into the well: it swells out of the text line and settles. */
.echo-combobox__chip {
  animation: echo-combobox-bud var(--echo-duration-pop) var(--echo-ease-pop) both;
  transform-origin: 100% 50%;
}
@keyframes echo-combobox-bud {
  from {
    opacity: 0;
    transform: scale(0.4);
  }
}
.echo-combobox__chip:focus-visible,
.echo-combobox__chip:focus-within {
  outline: 2px solid var(--echo-accent-ink, var(--echo-accent-glow));
  outline-offset: 1px;
}
/* The chevron: a small cap at the end of the well. */
.echo-combobox__trigger {
  position: relative;
  display: inline-grid;
  place-items: center;
  flex: none;
  width: calc(var(--ctl-h) - 2 * var(--echo-space-3));
  height: calc(var(--ctl-h) - 2 * var(--echo-space-3));
  max-height: 36px;
  max-width: 36px;
  padding: 0;
  border: 0;
  border-radius: var(--echo-radius-md);
  cursor: pointer;
  color: var(--echo-text-dim);
  background: linear-gradient(180deg, var(--echo-cap-highlight) 0%, var(--echo-cap) 50%, var(--echo-cap-shadow) 100%);
  box-shadow: var(
    --echo-shadow-key,
    inset 0 1px 0 rgb(255 255 255 / calc(0.3 * var(--echo-gloss, 1))),
    0 2px 0 var(--echo-seam)
  );
}
.echo-combobox__trigger svg {
  width: var(--echo-icon-sm, 14px);
  height: var(--echo-icon-sm, 14px);
  transition: transform var(--echo-duration-pop) var(--echo-ease-pop);
}
.echo-combobox__trigger[data-popup-open] svg {
  transform: rotate(180deg);
}
.echo-combobox__trigger:focus-visible {
  outline: 2px solid var(--echo-accent-ink, var(--echo-accent-glow));
  outline-offset: 2px;
}
/* A 24px target round the cap, at the smallest size. */
.echo-combobox__trigger::after {
  content: "";
  position: absolute;
  inset: min(0px, calc((100% - 24px) / 2));
}
.echo-combobox__list {
  outline: none;
}
.echo-combobox__empty:not(:empty) {
  padding: var(--echo-space-4) var(--echo-space-6);
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
}
/* "Create …" reads as an offer, not an existing option. */
.echo-select__item[data-create] {
  font-style: italic;
}
@media (prefers-reduced-motion: reduce) {
  .echo-combobox__chip {
    animation: none;
  }
  .echo-combobox__trigger svg {
    transition: none;
  }
}
@media (forced-colors: active) {
  .echo-combobox__well {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
  .echo-combobox__well:focus-within {
    outline: 2px solid Highlight;
  }
  .echo-combobox__trigger {
    border: var(--echo-border-hairline, 1px) solid ButtonText;
  }
}
